nodes.text_raw:
* { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --bg-base: #0a0d18;
  --fg: #f4f0e6;
  --fg-muted: rgba(244, 240, 230, 0.55);
  --fg-dim: rgba(244, 240, 230, 0.35);
  --accent: #ffb547;
  --card-bg: rgba(255, 255, 255, 0.03);
  --card-border: rgba(255, 255, 255, 0.08);
}

html, body {
  width: 1280px;
  height: 800px;
  overflow: hidden;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  background: var(--bg-base);
  color: var(--fg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.stage {
  position: relative;
  width: 1280px;
  height: 800px;
  overflow: hidden;
}

.bg-gradient {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #3d1f2e 0%, #0a0d18 55%);
  transition: background 1.5s ease;
}

.bg-glow {
  position: absolute;
  width: 1000px;
  height: 1000px;
  border-radius: 50%;
  filter: blur(120px);
  opacity: 0.38;
  top: -360px;
  right: -260px;
  background: radial-gradient(circle, #ff8c42 0%, transparent 70%);
  transition: background 1.5s ease;
  pointer-events: none;
}

.bg-glow-2 {
  position: absolute;
  width: 700px;
  height: 700px;
  border-radius: 50%;
  filter: blur(110px);
  opacity: 0.22;
  bottom: -260px;
  left: -160px;
  background: radial-gradient(circle, #4a7ba6 0%, transparent 70%);
  transition: background 1.5s ease;
  pointer-events: none;
}

.bg-grain {
  position: absolute;
  inset: 0;
  opacity: 0.06;
  mix-blend-mode: overlay;
  pointer-events: none;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='220' height='220'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%25' height='100%25' filter='url(%23n)'/></svg>");
}

.card {
  position: absolute;
  top: 50px;
  left: 50px;
  width: 1180px;
  height: 700px;
  padding: 42px 56px;
  background: var(--card-bg);
  border: 1px solid var(--card-border);
  border-radius: 28px;
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: 26px;
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  overflow: hidden;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding-bottom: 22px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}

.location h1 {
  font-size: 30px;
  font-weight: 500;
  letter-spacing: -0.02em;
  line-height: 1.1;
  margin-bottom: 6px;
}

.location .coords {
  font-size: 11px;
  color: var(--fg-muted);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.date-info {
  text-align: right;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}

.date-info .day {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.3em;
  color: var(--fg-muted);
}

.date-info .full-date {
  font-size: 22px;
  font-weight: 300;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
}

.today-badge {
  display: inline-block;
  margin-top: 2px;
  padding: 3px 11px;
  font-size: 9px;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--accent);
  background: rgba(255, 181, 71, 0.08);
  border: 1px solid rgba(255, 181, 71, 0.28);
  border-radius: 100px;
}

.hero {
  display: grid;
  grid-template-columns: 1fr 1.32fr;
  gap: 48px;
  align-items: center;
  min-height: 0;
}

.hero-left {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.weather-icon {
  width: 86px;
  height: 86px;
  color: var(--accent);
  transition: color 1s ease;
  animation: float 5s ease-in-out infinite;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-5px); }
}

.condition {
  font-size: 23px;
  font-weight: 300;
  letter-spacing: -0.01em;
  color: var(--fg);
}

.temp-display {
  display: flex;
  align-items: flex-start;
  margin-top: 2px;
}

.temp-max {
  font-size: 148px;
  font-weight: 200;
  line-height: 0.85;
  letter-spacing: -0.06em;
  font-variant-numeric: tabular-nums;
  background: linear-gradient(180deg, var(--fg) 0%, rgba(244, 240, 230, 0.62) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.temp-unit {
  font-size: 42px;
  font-weight: 300;
  margin-top: 18px;
  margin-left: 4px;
  color: var(--fg-muted);
}

.temp-range {
  display: flex;
  gap: 30px;
  font-variant-numeric: tabular-nums;
  margin-top: 2px;
}

.range-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.range-item .label {
  color: var(--fg-dim);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.28em;
}

.range-item .value {
  font-size: 18px;
  font-weight: 400;
}

.chart-container {
  position: relative;
  height: 100%;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.chart-title {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.28em;
  color: var(--fg-muted);
  margin-bottom: 10px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.chart-title .legend {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  color: var(--fg-dim);
  letter-spacing: 0.2em;
}

.chart-title .legend-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 8px var(--accent);
}

.chart-wrap {
  flex: 1;
  min-height: 240px;
  position: relative;
}

.chart-svg {
  width: 100%;
  height: 100%;
  display: block;
}

.hourly-strip {
  display: grid;
  grid-template-columns: repeat(24, 1fr);
  gap: 2px;
  padding-top: 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.hour-cell {
  text-align: center;
  padding: 7px 2px;
  border-radius: 8px;
  transition: background 0.2s;
}

.hour-cell:hover {
  background: rgba(255, 255, 255, 0.06);
}

.hour-cell .hour {
  font-size: 9px;
  color: var(--fg-dim);
  margin-bottom: 4px;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.05em;
}

.hour-cell .temp {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  color: var(--fg);
}

.state-message {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 14px;
  padding: 40px;
}

.state-message h2 {
  font-size: 26px;
  font-weight: 400;
  letter-spacing: -0.01em;
}

.state-message p {
  color: var(--fg-muted);
  max-width: 460px;
  line-height: 1.6;
  font-size: 14px;
}

.state-icon {
  color: var(--fg-dim);
  margin-bottom: 2px;
}

.loading-dots {
  display: flex;
  gap: 10px;
}

.loading-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--fg-muted);
  animation: pulse 1.4s infinite;
}

.loading-dot:nth-child(2) { animation-delay: 0.2s; }
.loading-dot:nth-child(3) { animation-delay: 0.4s; }

@keyframes pulse {
  0%, 80%, 100% { opacity: 0.3; transform: scale(0.7); }
  40% { opacity: 1; transform: scale(1); }
}

.loading-label {
  font-size: 11px;
  color: var(--fg-muted);
  text-transform: uppercase;
  letter-spacing: 0.3em;
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.card > .header { animation: fadeUp 0.6s ease 0.1s backwards; }
.card > .hero { animation: fadeUp 0.6s ease 0.25s backwards; }
.card > .hourly-strip { animation: fadeUp 0.6s ease 0.4s backwards; }

.chart-line {
  stroke-dasharray: 2200;
  stroke-dashoffset: 2200;
  animation: drawLine 1.6s ease forwards 0.7s;
}

@keyframes drawLine {
  to { stroke-dashoffset: 0; }
}

.chart-area {
  opacity: 0;
  animation: fadeIn 1s ease forwards 1.4s;
}

.chart-dot {
  opacity: 0;
  animation: fadeIn 0.4s ease forwards;
}

.chart-label {
  opacity: 0;
  animation: fadeIn 0.5s ease forwards;
}

.sun-rays {
  transform-origin: center;
  animation: rotate 60s linear infinite;
}

@keyframes rotate {
  to { transform: rotate(360deg); }
}

.rain-drop {
  animation: rainfall 1.5s linear infinite;
}

@keyframes rainfall {
  0% { transform: translateY(-3px); opacity: 0; }
  25% { opacity: 1; }
  75% { opacity: 1; }
  100% { transform: translateY(6px); opacity: 0; }
}

