function getQueryParams() {
  const params = new URLSearchParams(window.location.search);
  const today = new Date();
  const todayStr = today.toISOString().split('T')[0];

  let lat = parseFloat(params.get('lat'));
  if (isNaN(lat)) lat = 52.52;

  let lon = parseFloat(params.get('lon'));
  if (isNaN(lon)) lon = 13.405;

  let name = params.get('name') || 'Berlin';
  let date = params.get('date') || todayStr;

  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
    date = todayStr;
  }

  return { lat, lon, name, date };
}

function isToday(dateStr) {
  const today = new Date().toISOString().split('T')[0];
  return dateStr === today;
}

function isPastDate(dateStr) {
  const today = new Date();
  today.setUTCHours(0, 0, 0, 0);
  const date = new Date(dateStr + 'T00:00:00Z');
  return date < today;
}

function formatDate(dateStr) {
  const date = new Date(dateStr + 'T00:00:00Z');
  const days = ['SUNDAY', 'MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY', 'SATURDAY'];
  const months = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
  return {
    day: days[date.getUTCDay()],
    formatted: months[date.getUTCMonth()] + ' ' + date.getUTCDate() + ', ' + date.getUTCFullYear()
  };
}

async function fetchWeather(lat, lon, date) {
  const params = new URLSearchParams({
    latitude: lat,
    longitude: lon,
    daily: 'temperature_2m_max,temperature_2m_min,weather_code',
    hourly: 'temperature_2m',
    timezone: 'UTC',
    temperature_unit: 'celsius',
    start_date: date,
    end_date: date
  });

  const endpoint = isPastDate(date) ? '/api/om/archive' : '/api/om/forecast';
  const url = endpoint + '?' + params.toString();

  const response = await fetch(url);
  if (!response.ok) {
    throw new Error('The weather service responded with status ' + response.status + '.');
  }
  return response.json();
}

function smoothPath(points) {
  if (points.length < 2) return '';
  let d = 'M ' + points[0].x.toFixed(2) + ' ' + points[0].y.toFixed(2);

  for (let i = 0; i < points.length - 1; i++) {
    const p0 = points[i - 1] || points[i];
    const p1 = points[i];
    const p2 = points[i + 1];
    const p3 = points[i + 2] || p2;

    const cp1x = p1.x + (p2.x - p0.x) / 6;
    const cp1y = p1.y + (p2.y - p0.y) / 6;
    const cp2x = p2.x - (p3.x - p1.x) / 6;
    const cp2y = p2.y - (p3.y - p1.y) / 6;

    d += ' C ' + cp1x.toFixed(2) + ' ' + cp1y.toFixed(2) + ', ' + cp2x.toFixed(2) + ' ' + cp2y.toFixed(2) + ', ' + p2.x.toFixed(2) + ' ' + p2.y.toFixed(2);
  }
  return d;
}

function renderChart(temps, accentColor) {
  const width = 600;
  const height = 300;
  const padding = { top: 38, right: 24, bottom: 34, left: 38 };
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;

  const validTemps = temps.filter(t => t !== null && t !== undefined && !isNaN(t));
  if (validTemps.length === 0) {
    return '<div style="color:var(--fg-muted);padding:40px;text-align:center;font-size:13px;">No hourly data available</div>';
  }

  const minT = Math.min.apply(null, validTemps);
  const maxT = Math.max.apply(null, validTemps);
  const range = maxT - minT || 1;
  const pad = Math.max(range * 0.3, 1.5);
  const yMin = minT - pad;
  const yMax = maxT + pad;

  const points = temps.map((t, i) => {
    const x = padding.left + (i / Math.max(temps.length - 1, 1)) * chartWidth;
    const y = (t === null || t === undefined || isNaN(t))
      ? padding.top + chartHeight
      : padding.top + (1 - (t - yMin) / (yMax - yMin)) * chartHeight;
    return { x: x, y: y, temp: t, hour: i };
  });

  const validPoints = points.filter(p => p.temp !== null && p.temp !== undefined && !isNaN(p.temp));
  const linePath = smoothPath(validPoints);
  const lastP = validPoints[validPoints.length - 1];
  const firstP = validPoints[0];
  const areaPath = linePath + ' L ' + lastP.x.toFixed(2) + ' ' + (padding.top + chartHeight).toFixed(2) + ' L ' + firstP.x.toFixed(2) + ' ' + (padding.top + chartHeight).toFixed(2) + ' Z';

  const maxIdx = temps.indexOf(maxT);
  const minIdx = temps.indexOf(minT);

  const gridLines = [];
  const gridCount = 4;
  for (let i = 0; i <= gridCount; i++) {
    const y = padding.top + (i / gridCount) * chartHeight;
    const value = yMax - (i / gridCount) * (yMax - yMin);
    const isEdge = (i === 0 || i === gridCount);
    gridLines.push('<line x1="' + padding.left + '" y1="' + y.toFixed(2) + '" x2="' + (width - padding.right).toFixed(2) + '" y2="' + y.toFixed(2) + '" stroke="rgba(244,240,230,0.06)" stroke-width="1"' + (isEdge ? '' : ' stroke-dasharray="2 5"') + '/>');
    gridLines.push('<text x="' + (padding.left - 10) + '" y="' + (y + 3).toFixed(2) + '" text-anchor="end" fill="rgba(244,240,230,0.32)" font-size="10" font-family="inherit" font-variant-numeric="tabular-nums">' + Math.round(value) + '°</text>');
  }

  const hourMarks = [0, 6, 12, 18, 23];
  const hourLabels = hourMarks.map(function(h) {
    const x = padding.left + (h / Math.max(temps.length - 1, 1)) * chartWidth;
    return '<text x="' + x.toFixed(2) + '" y="' + (height - padding.bottom + 20).toFixed(2) + '" text-anchor="middle" fill="rgba(244,240,230,0.4)" font-size="10" font-family="inherit" font-variant-numeric="tabular-nums">' + h.toString().padStart(2, '0') + ':00</text>';
  }).join('');

  const dots = validPoints.map(function(p, i) {
    const originalIdx = points.indexOf(p);
    const isExtreme = originalIdx === maxIdx || originalIdx === minIdx;
    return '<circle cx="' + p.x.toFixed(2) + '" cy="' + p.y.toFixed(2) + '" r="' + (isExtreme ? 4 : 2.5) + '" fill="' + (isExtreme ? accentColor : 'rgba(244,240,230,0.55)') + '" class="chart-dot" style="animation-delay:' + (0.9 + i * 0.025) + 's"/>';
  }).join('');

  const maxPoint = points[maxIdx];
  const minPoint = points[minIdx];

  const maxLabel = maxPoint ? '<g class="chart-label" style="animation-delay:1.5s"><line x1="' + maxPoint.x.toFixed(2) + '" y1="' + (maxPoint.y - 8).toFixed(2) + '" x2="' + maxPoint.x.toFixed(2) + '" y2="' + (maxPoint.y - 18).toFixed(2) + '" stroke="' + accentColor + '" stroke-width="1" opacity="0.6"/><text x="' + maxPoint.x.toFixed(2) + '" y="' + (maxPoint.y - 22).toFixed(2) + '" text-anchor="middle" fill="' + accentColor + '" font-size="11" font-weight="500" font-family="inherit" font-variant-numeric="tabular-nums">' + Math.round(maxT) + '°</text></g>' : '';

  const minLabel = minPoint ? '<g class="chart-label" style="animation-delay:1.6s"><line x1="' + minPoint.x.toFixed(2) + '" y1="' + (minPoint.y + 8).toFixed(2) + '" x2="' + minPoint.x.toFixed(2) + '" y2="' + (minPoint.y + 18).toFixed(2) + '" stroke="rgba(244,240,230,0.5)" stroke-width="1" opacity="0.6"/><text x="' + minPoint.x.toFixed(2) + '" y="' + (minPoint.y + 30).toFixed(2) + '" text-anchor="middle" fill="rgba(244,240,230,0.85)" font-size="11" font-weight="500" font-family="inherit" font-variant-numeric="tabular-nums">' + Math.round(minT) + '°</text></g>' : '';

  return '<svg class="chart-svg" viewBox="0 0 ' + width + ' ' + height + '" preserveAspectRatio="xMidYMid meet">' +
    '<defs><linearGradient id="chartGrad" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="' + accentColor + '" stop-opacity="0.42"/><stop offset="100%" stop-color="' + accentColor + '" stop-opacity="0"/></linearGradient></defs>' +
    gridLines.join('') +
    hourLabels +
    '<path class="chart-area" d="' + areaPath + '" fill="url(#chartGrad)"/>' +
    '<path class="chart-line" d="' + linePath + '" fill="none" stroke="' + accentColor + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>' +
    dots +
    maxLabel +
    minLabel +
    '</svg>';
}

function applyTheme(themeName) {
  const theme = themes[themeName] || themes.clear;
  document.getElementById('bgGradient').style.background = theme.bg;
  document.getElementById('bgGlow').style.background = theme.glow;
  document.getElementById('bgGlow2').style.background = theme.glow2;
  document.documentElement.style.setProperty('--accent', theme.accent);
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, function(c) {
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
  });
}

function render(data, params) {
  const daily = data.daily;
  const hourly = data.hourly;

  if (!daily || !hourly || !Array.isArray(daily.temperature_2m_max) || daily.temperature_2m_max.length === 0) {
    renderError('No data available for the requested date.');
    return;
  }

  const maxTemp = Math.round(daily.temperature_2m_max[0]);
  const minTemp = Math.round(daily.temperature_2m_min[0]);
  const weatherCode = daily.weather_code[0];
  const weatherInfo = weatherCodes[weatherCode] || weatherCodes[0];

  applyTheme(weatherInfo.theme);

  const dateInfo = formatDate(params.date);
  const theme = themes[weatherInfo.theme] || themes.clear;
  const showTodayBadge = isToday(params.date);

  const hourlyTemps = hourly.temperature_2m || [];

  const card = document.getElementById('card');
  card.innerHTML =
    '<header class="header">' +
      '<div class="location">' +
        '<h1>' + escapeHtml(params.name) + '</h1>' +
        '<div class="coords">' + params.lat.toFixed(2) + '°N · ' + params.lon.toFixed(2) + '°E</div>' +
      '</div>' +
      '<div class="date-info">' +
        '<div class="day">' + dateInfo.day + '</div>' +
        '<div class="full-date">' + dateInfo.formatted + '</div>' +
        (showTodayBadge ? '<div class="today-badge">Today</div>' : '') +
      '</div>' +
    '</header>' +
    '<section class="hero">' +
      '<div class="hero-left">' +
        '<div class="weather-icon">' + getWeatherIcon(weatherInfo.icon) + '</div>' +
        '<div class="condition">' + escapeHtml(weatherInfo.label) + '</div>' +
        '<div class="temp-display">' +
          '<span class="temp-max">' + maxTemp + '</span>' +
          '<span class="temp-unit">°C</span>' +
        '</div>' +
        '<div class="temp-range">' +
          '<div class="range-item"><span class="label">High</span><span class="value">' + maxTemp + '°</span></div>' +
          '<div class="range-item"><span class="label">Low</span><span class="value">' + minTemp + '°</span></div>' +
          '<div class="range-item"><span class="label">Spread</span><span class="value">' + (maxTemp - minTemp) + '°</span></div>' +
        '</div>' +
      '</div>' +
      '<div class="chart-container">' +
        '<div class="chart-title"><span>Hourly temperature</span><span class="legend"><span class="legend-dot"></span>UTC</span></div>' +
        '<div class="chart-wrap">' + renderChart(hourlyTemps, theme.accent) + '</div>' +
      '</div>' +
    '</section>' +
    '<footer class="hourly-strip">' +
      hourlyTemps.map(function(temp, i) {
        return '<div class="hour-cell" title="' + i.toString().padStart(2, '0') + ':00 UTC">' +
          '<div class="hour">' + i.toString().padStart(2, '0') + '</div>' +
          '<div class="temp">' + (temp === null || temp === undefined || isNaN(temp) ? '—' : Math.round(temp) + '°') + '</div>' +
        '</div>';
      }).join('') +
    '</footer>';
}

function renderError(message) {
  const card = document.getElementById('card');
  card.innerHTML =
    '<div class="state-message">' +
      '<svg class="state-icon" width="56" height="56" viewBox="0 0 56 56" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">' +
        '<circle cx="28" cy="28" r="24"/>' +
        '<line x1="28" y1="18" x2="28" y2="32"/>' +
        '<circle cx="28" cy="38" r="1.2" fill="currentColor"/>' +
      '</svg>' +
      '<h2>Unable to load weather data</h2>' +
      '<p>' + escapeHtml(message) + '</p>' +
    '</div>';
}

async function init() {
  const params = getQueryParams();
  try {
    const data = await fetchWeather(params.lat, params.lon, params.date);
    render(data, params);
  } catch (err) {
    console.error('Weather fetch error:', err);
    renderError(err.message || 'An unexpected error occurred while fetching the weather data.');
  }
}

init();
